					culture_percent_state = {
						target = cu:promethean
						value >= 0.1
					}
					NOT = {
						state_region = {
							is_homeland = cu:promethean
						}
					}
				}
				state_region = {
					add_homeland = cu:promethean
				}
			}
		}

		# Caciquismo check
		handle_possible_absent_caciquismo_variables = yes

		if = {
			limit = {
				is_ai = yes
				NOT = { is_country_type = decentralized }
			}
			ai_assemble_decree_state_maps = yes
		}

		if = {
			limit = {
				is_subject = yes
