			}
			remove_modifier = modifier_reformed_captaincy_general
		}

		if = {
			limit = {
				country_has_voting_franchise = yes
				NOT = {
					modifier:country_electoral_confidence_over_time = 0
				}
				trigger_if = {
					limit = {
						modifier:country_electoral_confidence_over_time < 0
					}
					electoral_confidence > { # Can never drift to below 25%
						value = 0.25
						subtract = modifier:country_electoral_confidence_over_time
					}
				}
			}
			add_electoral_confidence = modifier:country_electoral_confidence_over_time
		}
