			limit = {
				has_dlc_feature = ep1_content
				c:KOR ?= {
					this = ROOT
					is_subject = yes
					overlord ?= {
						OR = {
							country_has_primary_culture = cu:han
							country_has_primary_culture = cu:manchu
						}
						has_technology_researched = electric_telegraph
					}
				}
				c:JAP ?= {
					NOT = {
						has_law_or_variant = law_type:law_isolationism
					}
					has_interest_marker_in_region = sr:region_northeast_asia
					has_technology_researched = electric_telegraph
				}
			}
			add_contextless_journal_entry = je_korean_rebellion
			c:JAP ?= {
				trigger_event = { id = gg_korea.7 popup = yes }
			}
			c:KOR.overlord ?= {
				trigger_event = { id = gg_korea.7 popup = yes }
			}
		}
		if = { # Script hack for Indian revolutions
			limit = {
				c:BIC ?= ROOT
				ROOT = {
					any_civil_war = {
						is_civil_war_type = revolution
						political_movement ?= {
							NOR = {
								is_political_movement_type = movement_religious_majority
								is_political_movement_type = movement_cultural_majority
								is_political_movement_type = movement_utilitarian
								culture ?= {
									has_discrimination_trait_group = heritage_group_european
								}
							}
						}
					}
				}
			}
			scope:target ?= {
				change_tag = BHT
				every_primary_culture = {
					save_temporary_scope_as = primary_culture_to_remove
					PREV ?= { # scope:target
						remove_primary_culture = scope:primary_culture_to_remove
						every_scope_character = {
							limit = {
								scope:primary_culture_to_remove ?= culture
							}
							retire_character = yes
						}
					}
				}
				grant_indian_cultures = yes
				if = {
					limit = {
						NOT = {
							has_law_or_variant = law_type:law_state_atheism
						}
					}
					if = {
						limit = {
							religion_percent_country = {
								target = rel:hindu
