								target = rel:sunni
								value >= 0.5
							}
						}
						set_state_religion = rel:sunni
					}
					else = {
						set_state_religion = rel:hindu
					}
				}
				india_independence_ig_effects = yes
				if = {
					limit = {
						has_modifier = modifier_india_crown_rule
					}
					remove_modifier = modifier_india_crown_rule
				}
				if = {
					limit = {
						has_modifier = modifier_india_company_rule
					}
					remove_modifier = modifier_india_company_rule
				}
				if = {
					limit = {
						has_modifier = modifier_india_company_rule_upgraded
					}
					remove_modifier = modifier_india_company_rule_upgraded
				}
				if = {
					limit = {
						has_modifier = modifier_indian_imperial_police
					}
					remove_modifier = modifier_indian_imperial_police
				}
				recalculate_pop_ig_support = yes
			}
		}
		### Carlists and Miguelists
		if = {
			limit = {
				scope:target ?= {
					is_secessionist = no
					has_law = law_type:law_monarchy
					OR = {
						var:civil_war_type_var ?= movement_type:movement_carlist
						var:civil_war_type_var ?= movement_type:movement_miguelist
					}
				}
			}
			scope:target ?= {
				if = {
					limit = {
						var:civil_war_type_var ?= movement_type:movement_carlist
					}
					country_generate_carlist_spain_ruler = yes
				}
				if = {
					limit = {
						var:civil_war_type_var ?= movement_type:movement_miguelist
					}
					country_generate_miguelist_portugal_ruler = yes
				}
			}
		}
		# Meiji civil wars
		if = {
			limit = {
				country_has_pending_meiji_restoration = yes
			}
			meiji_civil_war_effects = yes
		}
		set_variable = { name = recent_coup_or_revolution_var value = 0 }
	}
}

