on_harvest_condition_started_in_country = {
	effect = {
		if = {
			limit = {
				scope:intensity > 3
			}
			post_notification = harvest_condition_started_in_country_important
		}
		else = {
			post_notification = harvest_condition_started_in_country
		}
		if = {
			limit = {
				scope:state.state_region = {
					has_harvest_condition = earthquake
				}
			}
			scope:state.state_region = {
				start_earthquake_effect = yes
				spawn_entity_effect = {
					name = "earthquake_event_entity"
					duration = 10
				}
			}
			if = {
				limit = {
					has_dlc_feature = ip4_content
					scope:state = {
						has_building = building_manila_cathedral_original
					}
				}
				scope:state = {
					remove_building = building_manila_cathedral_original
					create_building={
						building="building_manila_cathedral_ruins"
						level=1
					}
				}
			}
			else_if = {
				limit = {
					has_dlc_feature = ip4_content
					scope:state = {
						has_building = building_manila_cathedral_monument
					}
					root = {
						NOT = {
							has_variable = manila_cathedral_cooldown_var
						}
					}
				}
				scope:state = {
					remove_building = building_manila_cathedral_monument
					create_building={
						building="building_manila_cathedral_ruins"
						level=1
					}
				}
				root = {
					trigger_event = {
						id = manila_cathedral.3
						days = 3
					}
				}
			}
		}
	}
}

